// Captures README screenshots from the synthetic demo project.
//
//   node scripts/capture-demo-screenshots.mjs [output-dir]
//
// Prerequisites:
//   - `npm --prefix desktop/ui run ux:build` built the isolated UX app;
//   - msedgedriver is cached by `make ux-setup`;
//   - tauri-driver is installed;
//   - the demo project was generated by `node scripts/make-demo-project.mjs`.
//
// The script copies the demo project into the isolated UX app data, launches
// the release binary through tauri-driver and drives the real UI over WebDriver.
// It never reads a real archive.

import { spawn, spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(import.meta.dirname, "..");
const APP = path.join(ROOT, "desktop", "target", "ux", "release", "gentree-desktop.exe");
const EDGE = path.join(
  ROOT,
  "desktop/ui/e2e/.cache/msedgedriver/msedgedriver.exe",
);
const LANG = process.env.CAPTURE_LANG === "en" ? "en" : "ru";
const DEMO = path.resolve(
  ROOT,
  process.env.CAPTURE_DEMO ??
    "demo/project/d3e00000-0000-4000-8000-000000000001",
);
const UX_IDENTIFIER = "com.gentree.desktop.ux";
const PORT = 4455;
const NATIVE_PORT = 9516;
const SESSION_PATH = `http://127.0.0.1:${PORT}`;
const OUT =
  process.argv[2] ??
  path.join(
    ROOT,
    "desktop/ui/e2e/artifacts",
    `demo-${new Date().toISOString().replace(/[:.]/g, "-")}`,
  );

const SHORT_NAMES = {
  "01-people": "people",
  "02-person-card": "person-card",
  "03-events": "events",
  "04-timeline": "timeline",
  "05-map": "map",
  "06-tree-ancestors": "tree-ancestors",
  "07-tree-descendants": "tree-descendants",
  "08-kinship": "kinship",
  "09-search-biography": "search-biography",
};

const COPY =
  LANG === "en"
    ? {
        projectName: "Demo: the Volkov family",
        homePerson: "Volkov Andrew Ilyich",
        open: "Open",
        people: "People",
        events: "Events",
        map: "Map",
        timeline: "Timeline",
        tree: "Tree",
        relation: "Relation",
        relationHeading: "Relation",
        search: "Search",
        ancestors: "Direct ancestors",
        descendants: "Direct descendants",
        findRelation: "Find relation",
        personSearch: "Name",
        searchQuery: "keeper",
        kinshipFromQuery: "Andrew",
        kinshipFromName: "Volkov Andrew Ilyich",
        kinshipToQuery: "Vera",
        kinshipToName: "Volkova Vera Mikhailovna",
      }
    : {
        projectName: "Демо: семья Волковых",
        homePerson: "Волков Андрей Ильич",
        open: "Открыть",
        people: "Люди",
        events: "События",
        map: "Карта",
        timeline: "Хронология",
        tree: "Дерево",
        relation: "Родство",
        relationHeading: "Связь",
        search: "Поиск",
        ancestors: "Прямые предки",
        descendants: "Прямые потомки",
        findRelation: "Найти связь",
        personSearch: "Имя, место",
        searchQuery: "хранитель",
        kinshipFromQuery: "Андрей",
        kinshipFromName: "Волков Андрей Ильич",
        kinshipToQuery: "Вера",
        kinshipToName: "Волкова Вера Михайловна",
      };

function fail(message) {
  console.error(`capture: ${message}`);
  process.exit(1);
}

if (!fs.existsSync(APP)) fail(`isolated app not found at ${APP}; run ux:build`);
if (!fs.existsSync(EDGE)) fail(`msedgedriver not found at ${EDGE}; run ux:setup`);
if (!fs.existsSync(DEMO)) fail(`demo project not found at ${DEMO}`);

// Seed the isolated app data. The normal app uses a different identifier.
const projectsDir = path.join(
  process.env.APPDATA ?? "",
  UX_IDENTIFIER,
  "projects",
);
fs.mkdirSync(projectsDir, { recursive: true });
const seeded = path.join(projectsDir, path.basename(DEMO));
fs.rmSync(seeded, { recursive: true, force: true });
fs.cpSync(DEMO, seeded, { recursive: true });

function driverBinary() {
  const found = spawnSync("where", ["tauri-driver"], { encoding: "utf8" });
  if (found.status === 0) {
    const line = found.stdout.split(/\r?\n/).find((item) => item.trim() !== "");
    if (line) return line.trim();
  }
  const fallback = path.join(
    process.env.USERPROFILE ?? "",
    ".cargo",
    "bin",
    "tauri-driver.exe",
  );
  if (fs.existsSync(fallback)) return fallback;
  fail("tauri-driver is not installed; run cargo install tauri-driver --locked");
}

function stopStale() {
  const script = [
    "$ErrorActionPreference='SilentlyContinue'",
    `Get-Process gentree-desktop | Where-Object { $_.Path -eq '${APP}' } | Stop-Process -Force`,
    "Get-Process tauri-driver | Stop-Process -Force",
    "Get-Process msedgedriver | Where-Object { $_.Path -like '*e2e*msedgedriver*' } | Stop-Process -Force",
    `foreach ($port in ${PORT}, ${NATIVE_PORT}) { Get-NetTCPConnection -LocalPort $port -State Listen | ForEach-Object { Stop-Process -Id $_.OwningProcess -Force } }`,
  ].join("; ");
  spawnSync("powershell", ["-NoProfile", "-NonInteractive", "-Command", script], {
    stdio: "ignore",
  });
  spawnSync("powershell", ["-NoProfile", "-NonInteractive", "-Command", "Start-Sleep -Milliseconds 700"], {
    stdio: "ignore",
  });
}

async function waitForPort() {
  const deadline = Date.now() + 20000;
  while (Date.now() < deadline) {
    try {
      const response = await fetch(`${SESSION_PATH}/status`);
      if (response.ok) return;
    } catch {
      // Not listening yet.
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  fail(`tauri-driver did not listen on ${PORT}`);
}

async function request(method, route, body) {
  const response = await fetch(`${SESSION_PATH}${route}`, {
    method,
    headers: body === undefined ? undefined : { "content-type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const payload = await response.json();
  if (!response.ok || (payload.value && payload.value.error)) {
    throw new Error(
      `${method} ${route}: ${payload.value?.error ?? payload.value?.message ?? response.status}`,
    );
  }
  return payload.value;
}

async function main() {
  stopStale();
  fs.mkdirSync(OUT, { recursive: true });
  const profile = path.join(ROOT, "desktop/ui/e2e/.cache/webview2-demo");
  fs.rmSync(profile, { recursive: true, force: true });
  fs.mkdirSync(profile, { recursive: true });

  const driver = spawn(
    driverBinary(),
    [
      "--port",
      String(PORT),
      "--native-port",
      String(NATIVE_PORT),
      "--native-driver",
      EDGE,
    ],
    {
      env: {
        ...process.env,
        WEBVIEW2_USER_DATA_FOLDER: profile,
        GENTREE_APP_LANGUAGE: LANG,
        GENTREE_APP_THEME: "dark",
        GENTREE_CHAT_ENABLED: "false",
      },
      stdio: ["ignore", "pipe", "pipe"],
    },
  );
  let driverLog = "";
  driver.stdout.on("data", (chunk) => (driverLog += chunk));
  driver.stderr.on("data", (chunk) => (driverLog += chunk));

  let sessionId = null;
  try {
    await waitForPort();
    const session = await request("POST", "/session", {
      capabilities: {
        alwaysMatch: {
          browserName: "wry",
          "tauri:options": { application: APP },
        },
      },
    });
    sessionId = session.sessionId;
    await request("POST", `/session/${sessionId}/window/rect`, {
      x: 20,
      y: 20,
      width: 1600,
      height: 1000,
    });
    await new Promise((resolve) => setTimeout(resolve, 700));

    const exec = (script, args = []) =>
      sessionId
        ? request("POST", `/session/${sessionId}/execute/sync`, { script, args })
        : Promise.reject(new Error("no session"));

    const waitFor = async (script, label, timeout = 25000, args = []) => {
      const deadline = Date.now() + timeout;
      while (Date.now() < deadline) {
        try {
          if (await exec(script, args)) return;
        } catch {
          // The page may be navigating.
        }
        await new Promise((resolve) => setTimeout(resolve, 250));
      }
      throw new Error(`timed out waiting for ${label}`);
    };

    const shot = async (name) => {
      await request("POST", `/session/${sessionId}/actions`, {
        actions: [
          {
            type: "pointer",
            id: "mouse",
            parameters: { pointerType: "mouse" },
            actions: [
              {
                type: "pointerMove",
                origin: "viewport",
                x: 1580,
                y: 980,
                duration: 0,
              },
            ],
          },
        ],
      }).catch(() => undefined);
      await new Promise((resolve) => setTimeout(resolve, 250));
      const data = await request("GET", `/session/${sessionId}/screenshot`);
      const fileName = process.env.CAPTURE_SHORT_NAMES
        ? (SHORT_NAMES[name] ?? name)
        : name;
      const file = path.join(OUT, `${fileName}.png`);
      fs.writeFileSync(file, Buffer.from(data, "base64"));
      console.log(`shot ${file}`);
    };

    const clickText = async (label, selector = "button") => {
      const clicked = await exec(
        `const label=arguments[0], selector=arguments[1];
         const node=[...document.querySelectorAll(selector)].find(
           (element) => element.textContent.replace(/\\s+/g," ").trim() === label,
         );
         if (!node) return false;
         node.click();
         return true;`,
        [label, selector],
      );
      if (!clicked) throw new Error(`button "${label}" not found`);
    };

    const waitHeading = (label) =>
      waitFor(
        `const heading=document.querySelector("h1, [role='heading']");
         return Boolean(heading && heading.textContent.trim() === arguments[0]);`,
        `heading "${label}"`,
        25000,
        [label],
      );

    const choosePerson = async (inputSelector, query, fullName) => {
      const opened = await exec(
        `const input=document.querySelector(arguments[0]);
         if (!input) return false;
         input.focus();
         input.click();
         const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
         setter.call(input, arguments[1]);
         input.dispatchEvent(new Event("input", { bubbles: true }));
         return true;`,
        [inputSelector, query],
      );
      if (!opened) throw new Error(`person input ${inputSelector} not found`);
      await new Promise((resolve) => setTimeout(resolve, 500));
      const picked = await exec(
        `const name=arguments[0];
         const option=[...document.querySelectorAll('[role="option"]')].find(
           (item) => item.textContent.replace(/\\s+/g, " ").includes(name),
         );
         if (!option) return false;
         option.click();
         return true;`,
        [fullName],
      );
      if (!picked) throw new Error(`person option "${fullName}" not found`);
      await new Promise((resolve) => setTimeout(resolve, 500));
    };

    await waitFor(
      `return document.title === "Gentree";`,
      "the Gentree window",
    );
    await new Promise((resolve) => setTimeout(resolve, 1200));

    // Projects -> demo project.
    await waitFor(
      `return document.body.innerText.includes(arguments[0]);`,
      "the demo project row",
      25000,
      [COPY.projectName],
    );
    const opened = await exec(
      `const name=arguments[0], label=arguments[1];
       const row=[...document.querySelectorAll("tr")].find((item) => item.innerText.includes(name));
       if (!row) return false;
       const button=[...row.querySelectorAll("button")].find(
         (item) => item.textContent.trim() === label,
       );
       if (!button) return false;
       button.click();
       return true;`,
      [COPY.projectName, COPY.open],
    );
    if (!opened) throw new Error("could not open the demo project");
    await waitHeading(COPY.people);
    await new Promise((resolve) => setTimeout(resolve, 1200));
    await shot("01-people");

    await clickText(COPY.homePerson);
    await waitFor(
      `const title=document.querySelector("#person-card-title");
       return Boolean(title && title.textContent.trim() === arguments[0]);`,
      "the person card",
      25000,
      [COPY.homePerson],
    );
    await new Promise((resolve) => setTimeout(resolve, 1200));
    await shot("02-person-card");

    await clickText(COPY.events, "nav button");
    await waitHeading(COPY.events);
    await new Promise((resolve) => setTimeout(resolve, 1200));
    await shot("03-events");

    await clickText(COPY.timeline, "nav button");
    await new Promise((resolve) => setTimeout(resolve, 2800));
    await shot("04-timeline");

    await clickText(COPY.map, "nav button");
    await waitHeading(COPY.map);
    await waitFor(
      `return document.querySelectorAll(".map-marker").length > 0;`,
      "the map points",
      30000,
    );
    await new Promise((resolve) => setTimeout(resolve, 5000));
    await shot("05-map");

    await clickText(COPY.tree, "nav button");
    await waitHeading(COPY.tree);
    await waitFor(
      `return document.querySelectorAll(".graph-node").length > 1;`,
      "the ancestor graph",
    );
    await clickText(COPY.ancestors);
    await new Promise((resolve) => setTimeout(resolve, 2200));
    await shot("06-tree-ancestors");

    await clickText(COPY.descendants);
    await new Promise((resolve) => setTimeout(resolve, 2600));
    await shot("07-tree-descendants");

    await clickText(COPY.relation, "nav button");
    await waitHeading(COPY.relationHeading);
    await choosePerson("#path-from", COPY.kinshipFromQuery, COPY.kinshipFromName);
    await choosePerson("#path-to", COPY.kinshipToQuery, COPY.kinshipToName);
    await clickText(COPY.findRelation);
    await waitFor(
      `return document.querySelectorAll(".path-chain-link").length > 0;`,
      "the kinship path",
    );
    await new Promise((resolve) => setTimeout(resolve, 1500));
    await shot("08-kinship");

    await clickText(COPY.search, "nav button");
    await waitHeading(COPY.search);
    await exec(
      `const input=document.querySelector('input[placeholder*="' + arguments[0] + '"]');
       if (!input) return false;
       const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
       setter.call(input, arguments[1]);
       input.dispatchEvent(new Event("input", { bubbles: true }));
       return true;`,
      [COPY.personSearch, COPY.searchQuery],
    );
    await new Promise((resolve) => setTimeout(resolve, 2200));
    await shot("09-search-biography");

    console.log(`screenshots: ${OUT}`);
  } catch (error) {
    console.error(`capture failed: ${error.message}`);
    if (sessionId) {
      try {
        const text = await request("POST", `/session/${sessionId}/execute/sync`, {
          script: "return document.body.innerText.slice(0, 2000);",
          args: [],
        });
        console.error(`page text:\n${text}`);
        const data = await request("GET", `/session/${sessionId}/screenshot`);
        fs.writeFileSync(path.join(OUT, "00-failure.png"), Buffer.from(data, "base64"));
      } catch {
        // The session may already be gone.
      }
    }
    if (driverLog.trim() !== "") console.error(driverLog.slice(-4000));
    process.exitCode = 1;
  } finally {
    if (sessionId) {
      await request("DELETE", `/session/${sessionId}`).catch(() => undefined);
    }
    driver.kill();
    stopStale();
  }
}

main();
